const prs = $input.all().map(i => i.json).flat();
const oneWeekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

const merged = prs.filter(pr => {
  if (!pr.merged_at) return false;
  return new Date(pr.merged_at) > oneWeekAgo;
});

const summary = merged.map(pr => {
  const labels = (pr.labels || []).map(l => l.name).join(', ');
  return `- #${pr.number}: ${pr.title} (by ${pr.user?.login || 'unknown'}) [${labels || 'no labels'}]`;
}).join('\n');

const stats = {
  total: merged.length,
  authors: [...new Set(merged.map(pr => pr.user?.login))],
  labels: [...new Set(merged.flatMap(pr => (pr.labels || []).map(l => l.name)))]
};

return [{
  json: {
    prList: summary || 'No PRs merged this week.',
    stats,
    weekOf: oneWeekAgo.toISOString().split('T')[0]
  }
}];

