const digest = $json.response || 'Could not generate digest.';
const ctx = $('Filter This Week').item.json;
const date = new Date().toISOString().split('T')[0];

const report = `# Sprint Digest — Week of ${ctx.weekOf}\n\n${digest}\n\n---\n*Generated ${date} by n8n + Ollama*\n`;

return [{ json: { report, filename: `digest-${ctx.weekOf}.md` } }];

const ctx = $input.item.json;
const binaryData = Buffer.from(ctx.report || '', 'utf8');
return [{
  json: ctx,
  binary: {
    report: {
      data: binaryData.toString('base64'),
      mimeType: 'text/markdown',
      fileName: ctx.filename
    }
  }
}];
